// Rebuilds the exact string ElevenLabs signed: "<timestamp>.<raw request body>"
const item = $input.first();
const headers = item.json.headers ?? {};
const header = String(headers['elevenlabs-signature'] ?? '');
const parts = {};
for (const piece of header.split(',')) {
  const i = piece.indexOf('=');
  if (i > 0) parts[piece.slice(0, i).trim()] = piece.slice(i + 1).trim();
}

// The raw body is needed: re-serialising parsed JSON would break the signature.
let raw = '';
try {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} catch (error) {
  raw = item.binary?.data?.data ? Buffer.from(item.binary.data.data, 'base64').toString('utf8') : '';
}

let payload = item.json.body ?? {};
if (raw) {
  try { payload = JSON.parse(raw); } catch (error) { /* keep parsed body */ }
}

const timestamp = Number(parts.t || 0);
const ageSeconds = timestamp ? Math.floor(Date.now() / 1000) - timestamp : 999999999;

return [{
  json: {
    signedPayload: `${parts.t ?? ''}.${raw}`,
    receivedSignature: parts.v0 ?? '',
    ageSeconds,
    payload,
  },
}];

// Maps the ElevenLabs transcription event to one call record (one row in the Data Table).
const s = $('Settings').first().json;
const list = (v) => String(v ?? '').split(',').map((w) => w.trim().toLowerCase()).filter(Boolean);

return $input.all().map((item) => {
  const p = item.json.payload ?? {};
  const d = p.data ?? {};
  const results = d.analysis?.data_collection_results ?? {};
  const pick = (id) => {
    const r = results[id];
    return r && r.value !== null && r.value !== undefined ? String(r.value).trim() : '';
  };
  const dyn = d.conversation_initiation_client_data?.dynamic_variables ?? {};
  const phone = pick(s.fieldCallbackNumber) || dyn.system__caller_id || d.metadata?.phone_call?.external_number || '';
  const urgency = (pick(s.fieldUrgency) || 'normal').toLowerCase();
  const topic = (pick(s.fieldTopic) || 'other').toLowerCase();
  const isSpam = list(s.spamTopics).includes(topic);
  return {
    json: {
      conversation_id: String(d.conversation_id ?? ''),
      received_at: new Date((p.event_timestamp ?? Math.floor(Date.now() / 1000)) * 1000).toISOString(),
      caller_name: pick(s.fieldCallerName) || 'Unknown caller',
      caller_phone: String(phone),
      reason: pick(s.fieldReason),
      topic,
      urgency: list(s.urgentValues).includes(urgency) ? 'urgent' : urgency,
      callback_time: pick(s.fieldCallbackTime),
      summary: String(d.analysis?.transcript_summary ?? '').slice(0, 2000),
      duration_secs: Number(d.metadata?.call_duration_secs ?? 0),
      agent_name: String(d.agent_name ?? ''),
      status: isSpam ? 'spam' : 'new',
      attempts: 0,
      reminders_sent: 0,
    },
  };
});

// Builds the Telegram alert text and the three signed action links for each new call.
const s = $('Settings').first().json;
const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// One Telegram text for a call row, used for alerts, reminders and edited messages.
const render = (r, header) => [
  header,
  `<b>Caller:</b> ${esc(r.caller_name)}`,
  `<b>Phone:</b> ${esc(r.caller_phone || 'not given')}`,
  r.reason ? `<b>Reason:</b> ${esc(r.reason)}` : '',
  r.topic && r.topic !== 'other' ? `<b>Topic:</b> ${esc(r.topic)}` : '',
  r.callback_time ? `<b>Best time:</b> ${esc(r.callback_time)}` : '',
  r.summary ? `\n${esc(String(r.summary).slice(0, 600))}` : '',
].filter(Boolean).join('\n');
return $input.all().map((item, i) => {
  // Paired item lookup keeps the right call even after duplicates were skipped.
  const r = { ...($('Sign the action links').itemMatching(i)?.json ?? {}), ...item.json };
  const link = (action) => `${s.actionWebhookUrl}?id=${encodeURIComponent(r.conversation_id)}&action=${action}&token=${r.action_token}`;
  const header = r.urgency === 'urgent'
    ? `🔴 <b>URGENT callback</b> (${esc(r.agent_name || 'voice agent')})`
    : `📞 <b>New call</b> (${esc(r.agent_name || 'voice agent')})`;
  return {
    json: {
      conversation_id: r.conversation_id,
      alert_text: render(r, header),
      link_called_back: link('called_back'),
      link_no_answer: link('no_answer'),
      link_spam: link('spam'),
    },
  };
});

