// Outbound calls that did not connect (busy, no answer) become a row with status failed_outbound.
const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return $input.all().map((item) => {
  const p = item.json.payload ?? {};
  const d = p.data ?? {};
  const body = d.metadata?.body ?? {};
  const to = String(body.to_number ?? body.To ?? body.Called ?? '');
  const reason = String(d.failure_reason ?? 'unknown');
  return {
    json: {
      conversation_id: String(d.conversation_id ?? ''),
      received_at: new Date((p.event_timestamp ?? Math.floor(Date.now() / 1000)) * 1000).toISOString(),
      caller_name: 'Outbound call',
      caller_phone: to,
      reason: `Outbound call failed: ${reason}`,
      topic: 'outbound',
      urgency: 'normal',
      status: 'failed_outbound',
      attempts: 1,
      reminders_sent: 0,
      alert_text: `⚠️ <b>Outbound call failed</b>\n<b>To:</b> ${esc(to || 'unknown number')}\n<b>Reason:</b> ${esc(reason)}`,
    },
  };
});

// Validates the clicked link and decides the new status of the call.
const s = $('Settings').first().json;
const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// One Telegram text for a call row, used for alerts, reminders and edited messages.
const render = (r, header) => [
  header,
  `<b>Caller:</b> ${esc(r.caller_name)}`,
  `<b>Phone:</b> ${esc(r.caller_phone || 'not given')}`,
  r.reason ? `<b>Reason:</b> ${esc(r.reason)}` : '',
  r.topic && r.topic !== 'other' ? `<b>Topic:</b> ${esc(r.topic)}` : '',
  r.callback_time ? `<b>Best time:</b> ${esc(r.callback_time)}` : '',
  r.summary ? `\n${esc(String(r.summary).slice(0, 600))}` : '',
].filter(Boolean).join('\n');
const q = $('Receive callback action link').first().json.query ?? {};
const expected = $('Check the action link').first().json.expected_token;
const row = $input.first().json ?? {};
const labels = { called_back: '✅ Called back', no_answer: '📵 No answer', spam: '🚫 Marked as spam' };
const page = (title, text) => `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title}</title></head>` +
  `<body style="font-family:system-ui,sans-serif;max-width:32rem;margin:3rem auto;padding:0 1rem"><h2>${title}</h2><p>${text}</p></body></html>`;
const fail = (code, title, text) => [{ json: { apply: false, http_code: code, page_html: page(title, text) } }];

if (!q.token || String(q.token) !== String(expected)) return fail(403, 'Link not valid', 'This link is invalid or has been changed.');
if (!labels[q.action]) return fail(400, 'Unknown action', 'Use the buttons in the Telegram message.');
if (!row.conversation_id) return fail(404, 'Call not found', 'This call is not in the call log any more.');
if (['called_back', 'spam'].includes(row.status) && row.status === q.action) {
  return fail(200, 'Already done', `${esc(row.caller_name)} is already marked: ${labels[q.action]}.`);
}

const now = $now.toUTC().toISO();
const local = $now.setZone(s.timezone || 'UTC').toFormat('d LLL HH:mm');
const attempts = Number(row.attempts || 0) + (q.action === 'spam' ? 0 : 1);
const update = {
  status: q.action,
  attempts,
  handled_at: q.action === 'no_answer' ? (row.handled_at || null) : now,
  last_reminder_at: q.action === 'no_answer' ? now : (row.last_reminder_at || null),
};
const note = q.action === 'no_answer'
  ? `${labels[q.action]} (attempt ${attempts}) · ${local}. A reminder follows in ${s.noAnswerRetryMinutes} min.`
  : `${labels[q.action]} · ${local}`;
return [{
  json: {
    apply: true,
    http_code: 200,
    conversation_id: row.conversation_id,
    telegram_message_id: row.telegram_message_id ?? '',
    ...update,
    edited_text: `${render(row, `<b>${esc(row.caller_name)}</b>`)}\n\n${note}`,
    page_html: page(labels[q.action], `${esc(row.caller_name)} (${esc(row.caller_phone || 'no phone')}): ${note}`),
  },
}];

// Finds open callbacks that waited too long and are still allowed another reminder.
const s = $('Settings').first().json;
const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// One Telegram text for a call row, used for alerts, reminders and edited messages.
const render = (r, header) => [
  header,
  `<b>Caller:</b> ${esc(r.caller_name)}`,
  `<b>Phone:</b> ${esc(r.caller_phone || 'not given')}`,
  r.reason ? `<b>Reason:</b> ${esc(r.reason)}` : '',
  r.topic && r.topic !== 'other' ? `<b>Topic:</b> ${esc(r.topic)}` : '',
  r.callback_time ? `<b>Best time:</b> ${esc(r.callback_time)}` : '',
  r.summary ? `\n${esc(String(r.summary).slice(0, 600))}` : '',
].filter(Boolean).join('\n');
const local = $now.setZone(s.timezone || 'UTC');
if (local.hour < Number(s.workdayStartHour) || local.hour >= Number(s.workdayEndHour)) return [];

const minutesSince = (iso) => (Date.now() - new Date(iso).getTime()) / 60000;
const link = (r, action) => `${s.actionWebhookUrl}?id=${encodeURIComponent(r.conversation_id)}&action=${action}&token=${r.action_token}`;

return $input.all()
  .map((i) => i.json)
  .filter((r) => r.conversation_id && ['new', 'no_answer'].includes(r.status))
  .filter((r) => Number(r.reminders_sent || 0) < Number(s.maxReminders))
  .filter((r) => {
    const wait = r.status === 'no_answer' ? s.noAnswerRetryMinutes
      : r.urgency === 'urgent' ? s.urgentReminderMinutes : s.normalReminderMinutes;
    return minutesSince(r.last_reminder_at || r.received_at) >= Number(wait);
  })
  .map((r) => {
    const age = Math.round(minutesSince(r.received_at));
    const n = Number(r.reminders_sent || 0) + 1;
    const header = `⏰ <b>Reminder ${n}/${s.maxReminders}:</b> ${r.status === 'no_answer' ? 'try again' : 'call back'} (waiting ${age} min)`;
    return {
      json: {
        conversation_id: r.conversation_id,
        reminders_sent: n,
        alert_text: render(r, header),
        link_called_back: link(r, 'called_back'),
        link_no_answer: link(r, 'no_answer'),
        link_spam: link(r, 'spam'),
      },
    };
  });

// Summarises today's calls and the open callbacks into one Telegram message.
const s = $('Settings').first().json;
const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const tz = s.timezone || 'UTC';
const today = $now.setZone(tz).toISODate();
const dayOf = (iso) => (iso ? DateTime.fromISO(new Date(iso).toISOString()).setZone(tz).toISODate() : '');
const rows = $input.all().map((i) => i.json).filter((r) => r.conversation_id);

const todays = rows.filter((r) => dayOf(r.received_at) === today);
const inbound = todays.filter((r) => !['spam', 'failed_outbound'].includes(r.status));
const handledToday = rows.filter((r) => r.status === 'called_back' && dayOf(r.handled_at) === today);
const waits = handledToday.map((r) => (new Date(r.handled_at) - new Date(r.received_at)) / 60000).filter((m) => m >= 0);
const avgWait = waits.length ? Math.round(waits.reduce((a, b) => a + b, 0) / waits.length) : null;
const open = rows.filter((r) => ['new', 'no_answer'].includes(r.status))
  .sort((a, b) => new Date(a.received_at) - new Date(b.received_at));
const topics = {};
for (const r of inbound) topics[r.topic || 'other'] = (topics[r.topic || 'other'] || 0) + 1;
const topTopics = Object.entries(topics).sort((a, b) => b[1] - a[1]).slice(0, 3).map(([t, n]) => `${esc(t)} ${n}`).join(', ');

const lines = [
  `📊 <b>Calls report, ${today}</b>`,
  `Calls today: <b>${inbound.length}</b> (urgent ${inbound.filter((r) => r.urgency === 'urgent').length}, spam ${todays.filter((r) => r.status === 'spam').length}, failed outbound ${todays.filter((r) => r.status === 'failed_outbound').length})`,
  topTopics ? `Topics: ${topTopics}` : '',
  `Called back today: <b>${handledToday.length}</b>${avgWait !== null ? `, average wait ${avgWait} min` : ''}`,
  `Still open: <b>${open.length}</b>`,
  ...open.slice(0, 5).map((r) => `• ${esc(r.caller_name)} ${esc(r.caller_phone)}${r.urgency === 'urgent' ? ' 🔴' : ''}${Number(r.reminders_sent || 0) >= Number(s.maxReminders) ? ' (no more reminders)' : ''}`),
  open.length > 5 ? `…and ${open.length - 5} more in the Data Table.` : '',
].filter(Boolean);
return [{ json: { report_text: lines.join('\n') } }];
